import Link from "next/link";
import { useEffect, useMemo, useState, type CSSProperties } from "react";
import type { CurriculumLesson, CurriculumQuestion } from "@/content/part1-curriculum";
import { Unit2ActivityRenderer, Unit2Challenge, Unit2FinalReview, type SavedUnit2Mistake } from "@/components/unit2-interactives";
import { Unit3ActivityRenderer, Unit3Challenge } from "@/components/unit3-interactives";
import { Unit4ActivityRenderer, Unit4Challenge } from "@/components/unit4-interactives";
