  if (visual === "edge") return <figure className="edu-diagram edu-compute"><figcaption><Network /><DiagramLabel locale={locale} en="Cloud computing and edge computing" ar="الحوسبة السحابية والحوسبة الطرفية" /></figcaption><div className="compute-columns"><section className="cloud-route"><h3><Cloud /> <DiagramLabel locale={locale} en="Cloud route" ar="مسار السحابة" /></h3><div className="route-flow"><span><Car /><DiagramLabel locale={locale} en="Vehicle & sensors" ar="المركبة والمستشعرات" /></span><i /><span><Wifi /><DiagramLabel locale={locale} en="Internet" ar="الإنترنت" /></span><i /><span><Server /><DiagramLabel locale={locale} en="Cloud server" ar="خادم سحابي" /></span><i /><span><Cpu /><DiagramLabel locale={locale} en="Processing" ar="معالجة" /></span><i /><span><Car /><DiagramLabel locale={locale} en="Response" ar="استجابة" /></span></div><p className="latency-note"><span className="latency-bars"><i /><i /><i /></span><DiagramLabel locale={locale} en="Network trip can add delay" ar="قد تضيف الرحلة عبر الشبكة تأخرًا" /></p></section><section className="edge-route"><h3><Cpu /> <DiagramLabel locale={locale} en="Edge route" ar="مسار الطرف" /></h3><div className="route-flow"><span><Car /><DiagramLabel locale={locale} en="Vehicle & sensors" ar="المركبة والمستشعرات" /></span><i /><span><Cpu /><DiagramLabel locale={locale} en="Local edge processing" ar="معالجة طرفية محلية" /></span><i /><span><ShieldCheck /><DiagramLabel locale={locale} en="Immediate decision" ar="قرار فوري" /></span></div><p className="latency-note fast"><CheckCircle2 /><DiagramLabel locale={locale} en="Low latency for time-critical decisions" ar="زمن تأخر منخفض للقرارات الحساسة للوقت" /></p></section></div></figure>;
